46	Tensor CvtColorInto(Tensor &output, Tensor &input, NVCVColorConversionCode code, std::optional<Stream> pstream)
47	{
48	    if (!pstream)
49	    {
50	        pstream = Stream::Current();
51	    }
52	
53	    auto cvtColor = CreateOperator<cvcuda::CvtColor>();
54	
55	    ResourceGuard guard(*pstream);
56	    guard.add(LockMode::LOCK_MODE_READ, {input});
57	    guard.add(LockMode::LOCK_MODE_WRITE, {output});
58	    guard.add(LockMode::LOCK_MODE_NONE, {*cvtColor});
59	
60	    guard.run([&cvtColor, &pstream, &input, &output, &code]()
61	              { cvtColor->submit(pstream->cudaHandle(), input, output, code); });
62	
63	    return output;
64	}
65	
66	Tensor CvtColor(Tensor &input, NVCVColorConversionCode code, std::optional<Stream> pstream)
67	{
68	    nvcv::ImageFormat outputFormat = GetOutputFormat(input.dtype(), code);
69	    nvcv::TensorShape outputShape  = GetOutputTensorShape(input.shape(), outputFormat, code);
70	    nvcv::DataType    outputDType  = outputFormat.planeDataType(0).channelType(0);
71	
72	#ifndef NDEBUG
73	    assert(outputFormat.numPlanes() == 1);
74	    nvcv::DataType channelDType = outputFormat.planeDataType(0).channelType(0);
75	    for (int c = 1; c < outputFormat.planeDataType(0).numChannels(); ++c)
76	    {
77	        assert(channelDType == outputFormat.planeDataType(0).channelType(c));
78	    }
79	#endif
80	
81	    Tensor output = Tensor::Create(outputShape, outputDType);
82	
83	    return CvtColorInto(output, input, code, pstream);
84	}
85	
86	bool IsPlanarVarShapeFormat(nvcv::ImageFormat format)
87	{
88	    return format.numPlanes() > 1 && format.numPlanes() == format.numChannels();
89	}
90	
91	nvcv::ImageFormat PlanarRGBOutputFormat(nvcv::ImageFormat outputFormat)
92	{
93	    if (nvcv::DataType channelType = outputFormat.planeDataType(0).channelType(0); channelType != nvcv::TYPE_U8)
94	    {
95	        throw CvtColorOpError{"Unsupported planar var-shape CvtColor output data type"};
96	    }
97	
98	    switch (outputFormat.swizzle())
99	    {
100	    case nvcv::Swizzle::S_XYZ1:
101	    case nvcv::Swizzle::S_XYZ0:
102	        return nvcv::ImageFormat{NVCV_IMAGE_FORMAT_RGB8p};
103	    case nvcv::Swizzle::S_ZYX1:
104	    case nvcv::Swizzle::S_ZYX0:
105	        return nvcv::ImageFormat{NVCV_IMAGE_FORMAT_BGR8p};
106	    case nvcv::Swizzle::S_XYZW:
107	        return nvcv::ImageFormat{NVCV_IMAGE_FORMAT_RGBA8p};
108	    case nvcv::Swizzle::S_ZYXW:
109	        return nvcv::ImageFormat{NVCV_IMAGE_FORMAT_BGRA8p};
110	    default:
111	        return outputFormat;
112	    }
113	}
114	
115	nvcv::ImageFormat PreservePlanarVarShapeOutput(nvcv::ImageFormat inputFormat, nvcv::ImageFormat outputFormat)
116	{
117	    if (!IsPlanarVarShapeFormat(inputFormat))
118	    {
119	        return outputFormat;
120	    }
121	
122	    if (outputFormat.numPlanes() != 1)
123	    {
124	        return outputFormat;
125	    }
126	
127	    if (outputFormat.colorModel() == nvcv::ColorModel::RGB)
128	    {
129	        return PlanarRGBOutputFormat(outputFormat);
130	    }
131	
132	    if (outputFormat.colorModel() == nvcv::ColorModel::YCbCr
133	        && outputFormat.chromaSubsampling() == nvcv::ChromaSubsampling::NONE && outputFormat.numChannels() == 3)
134	    {
135	        if (nvcv::DataType channelType = outputFormat.planeDataType(0).channelType(0); channelType == nvcv::TYPE_U8)
136	        {
137	            return nvcv::ImageFormat{NVCV_IMAGE_FORMAT_YUV8p};
138	        }
139	        throw CvtColorOpError{"Unsupported planar var-shape CvtColor YUV output data type"};
140	    }
141	
142	    return outputFormat;
143	}
