173	    }
174	    auto outFormat = GetOutputFormat(inFormat.planeDataType(0), code);
175	    outFormat      = PreservePlanarVarShapeOutput(inFormat, outFormat);
176	
177	    ImageBatchVarShape output = CreateSameShapeImageBatch(input, outFormat);
178	
179	    return CvtColorVarShapeInto(output, input, code, pstream);
